# c309: 튜토리얼 바리케이트를 큰 맵 바리케이트 그대로로 (길이·고정·안 밀림 등 덧댄 것 전부 뺌) · 강철문 너머 2개 나란히 · 넓은 복도 3개씩 두 줄
C309_R = [('const barr = (x, z, h, len) => { const car = chParked(x, z, h, true); car.kl = len / CAR_L; car.g.scale.set(car.kl, 1, 1); car.massK = 1e6; car.tutS = buildings.find((B) => x > B.x0 && x < B.x1 && z > B.z0 && z < B.z1 && CH_TUTT.has(B.type)); car.tutX = x; car.tutZ = z; car.tutH = h; return car; };', 'const barr = (x, z, h) => { const car = chParked(x, z, h, true); car.tutS = buildings.find((B) => x > B.x0 && x < B.x1 && z > B.z0 && z < B.z1 && CH_TUTT.has(B.type)); return car; }, Lp = CAR_L + 0.05;   // c309: 큰 맵 바리케이트 그대로 (크기·무게·밀림 같음) — tutS = 그 복도 안에서 칠 수 있게만'), ('barr(C5.x0 + 1.3, C5.z1 - 7, 0, 2.6); barr(C5.x1 - 1.3, C5.z1 - 7.7, 0, 2.6);', 'for (const s of [-0.5, 0.5]) barr((C5.x0 + C5.x1) / 2 + s * Lp, C5.z1 - 7, 0);   // c309: 바리케이트 둘 — 큰 맵처럼 나란히'), ('for (const [dx, dz] of [[0, -2.1], [0, 0], [0, 2.1], [0.75, -1.1], [0.75, 1.1], [0.75, 0]]) barr(C7.x0 + 10 + dx, zc + dz, Math.PI / 2, dx ? 2.6 : 2.6);', 'for (const dx of [0, 1.25]) for (const k of [-1, 0, 1]) barr(C7.x0 + 10 + dx, zc + k * Lp, Math.PI / 2);   // c309: 바리케이트 여섯 — 큰 맵처럼 셋씩 두 줄'), ('      if (CH_TUT && car.z > MM.z1 + 5) { if (car.tutX !== undefined) { car.x = car.tutX; car.z = car.tutZ; car.h = car.tutH; car.vx = car.vz = 0; } continue; }', '      if (CH_TUT && car.z > MM.z1 + 5) continue;   // c301 · c309: 튜토리얼 구역의 차는 지도 경계에만 안 묶인다 (그 밖은 큰 맵과 같다)'), ('\n      if (A.tutX !== undefined || B.tutX !== undefined) continue;   // c308: 튜토리얼 바리케이트는 제자리 고정 — 서로·다른 차와 밀어내지 않는다', ''), (' && car.tutX === undefined   /* c308: 튜토리얼 바리케이트는 좀비도 못 민다 */', '')]
